"""
title: LangChain Ollama Pipeline
author: mobile-ssh
version: 1.0
license: MIT
description: Runs a local Ollama model via LangChain (ChatOllama) and exposes it as an OpenAI-compatible model.
requirements: langchain-ollama, langchain-core
"""
from typing import List, Union, Generator, Iterator
from pydantic import BaseModel


class Pipeline:
    class Valves(BaseModel):
        # Reachable from inside the Pipelines container to Ollama on the host.
        OLLAMA_BASE_URL: str = "http://host.docker.internal:11434"
        MODEL: str = "llama3.2"
        TEMPERATURE: float = 0.7

    def __init__(self):
        self.name = "LangChain Ollama"
        self.valves = self.Valves()
        self.llm = None

    async def on_startup(self):
        from langchain_ollama import ChatOllama
        self.llm = ChatOllama(
            base_url=self.valves.OLLAMA_BASE_URL,
            model=self.valves.MODEL,
            temperature=self.valves.TEMPERATURE,
        )

    async def on_shutdown(self):
        self.llm = None

    def _to_lc_messages(self, messages, user_message):
        from langchain_core.messages import SystemMessage, HumanMessage, AIMessage
        lc = []
        for m in messages or []:
            role = m.get("role")
            content = m.get("content", "")
            if role == "system":
                lc.append(SystemMessage(content=content))
            elif role == "assistant":
                lc.append(AIMessage(content=content))
            else:
                lc.append(HumanMessage(content=content))
        if not lc:
            lc.append(HumanMessage(content=user_message))
        return lc

    def pipe(self, user_message: str, model_id: str, messages: List[dict], body: dict) -> Union[str, Generator, Iterator]:
        lc_messages = self._to_lc_messages(messages, user_message)
        try:
            if body.get("stream", False):
                def gen():
                    for chunk in self.llm.stream(lc_messages):
                        if chunk.content:
                            yield chunk.content
                return gen()
            return self.llm.invoke(lc_messages).content
        except Exception as e:
            return f"Error: {e}"
PYEOF
docker cp /tmp/mobilessh-langchain-pipe.py pipelines:/app/pipelines/langchain_ollama_pipe.py && docker restart pipelines
